  "claim": {
    "component_id": "C040.main",
    "value": "Without the stated conditions of valid random assignment, comparable follow-up and reliable outcome capture, a publication difference should be treated as an association.",
    "scope": "The fallback interpretation when the stated causal-support conditions do not hold.",
    "provenance": {
      "refs": [
        {
          "source_id": "P020",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "The span explicitly supplies the causal-support conditions and the fallback interpretation."
    }
  },
  "signal_basis": {
    "component_id": "C040.signal_basis",
    "value": "Compare first-publication proportions for the change and comparison flow within a predefined observation window. Assume an observed difference while the stated causal-support conditions do not hold; recording artifacts, group differences and incomplete follow-up can limit its interpretation.",
    "scope": "Proposed release evaluation, interpreted as an observed association with causal interpretation withheld when checks fail or evidence is too sparse.",
